package org.sleepwell.app;

import android.app.Activity;
import android.content.SharedPreferences;
import android.os.Bundle;
import android.widget.*;
import java.util.*;

/** Silent ordered draft, applied only by Save. Existing local document playlist remains intact. */
final class AmbientRotationEditor {
    private final Activity activity;private final Runnable finished;private final SharedPreferences preferences;
    private SoundMix previous;private final List<String> sounds=new ArrayList<>();private int minutes=5;private long revision;private String error="";private android.app.Dialog picker;
    AmbientRotationEditor(Activity activity,Bundle saved,Runnable finished){this.activity=activity;this.finished=finished;preferences=SoundPreferences.factory.open(activity);try{previous=SoundPreferences.load(preferences).copy();sounds.addAll(previous.rotation.sounds);minutes=previous.rotation.minutes;revision=SoundPreferences.revision(preferences);if(saved!=null){ArrayList<String> restored=saved.getStringArrayList("sounds");if(restored==null||restored.size()>AmbientRotation.SOURCES.size())throw new IllegalArgumentException();Set<String> unique=new HashSet<>();for(String sound:restored)if(!AmbientRotation.SOURCES.contains(sound)||!unique.add(sound))throw new IllegalArgumentException();sounds.clear();sounds.addAll(restored);minutes=saved.getInt("minutes",minutes);if(!Set.of(5,10,15).contains(minutes))throw new IllegalArgumentException();revision=saved.getLong("revision",revision);error=saved.getString("error","");}}catch(RuntimeException invalid){previous=null;error="The saved mix or rotation could not be read. Return to Sleep sounds and select a new mix.";}}
    Bundle state(){Bundle out=new Bundle();out.putStringArrayList("sounds",new ArrayList<>(sounds));out.putInt("minutes",minutes);out.putLong("revision",revision);out.putString("error",error);return out;}
    void render(){LinearLayout body=Design.page(activity,false,null,n->{});RecordUi.label(activity,body);RecordUi.header(body,"Ambient rotation",finished);Design.space(body,12);Design.text(body,"A changing background",25,600,Design.INK);Design.space(body,8);Design.text(body,"Choose an order for the bundled sounds. Each loop plays for the selected amount of playing time, then the next begins. The order repeats until your overall timer or Stop.",14,400,Design.MUTED);Design.space(body,16);
        if(previous==null){Design.text(body,error,14,500,Design.BROWN);Design.button(body,"Back",false,finished);return;}
        if(sounds.isEmpty())Design.text(body,"Add at least two sounds",16,500,Design.MUTED);
        for(int i=0;i<sounds.size();i++){int index=i;Design.item(body,"wave",(i+1)+". "+sounds.get(i),"Order or remove",()->options(index));Design.line(body);}
        Design.space(body,12);Button add=Design.button(body,"Add ambient sound",false,this::add);RecordUi.enabled(add,sounds.size()<AmbientRotation.SOURCES.size());Design.space(body,8);Design.item(body,"clock","Change sound every",minutes+" min playing",()->picker=SleepPicker.choices(activity,"Rotation interval",new String[]{"5 min","10 min","15 min"},minutes/5-1,index->{minutes=new int[]{5,10,15}[index];render();}));Design.line(body);
        Design.space(body,14);Design.text(body,"Pause freezes both the interval and overall timer. The mix fade and optional tracking-owned stillness fade apply to every sound. The brown-noise background is muted while Brown noise is the primary sound.",13,400,Design.MUTED);Design.space(body,10);Design.text(body,"Save is silent and pauses the current mix. Return and tap Play, or use the existing Play when tracking starts switch for a future recording. No new automatic-play permission is enabled here.",13,500,Design.BROWN);
        if(!error.isEmpty()){Design.space(body,10);Design.text(body,error,13,500,0xffa93919);}LinearLayout footer=RecordUi.footer(body);Design.button(footer,"Save rotation",true,this::save);Design.button(footer,"Cancel",false,finished);
    }
    private void add(){List<String> remaining=new ArrayList<>(AmbientRotation.SOURCES);remaining.removeAll(sounds);if(remaining.isEmpty())return;picker=SleepPicker.choices(activity,"Add ambient sound",remaining.toArray(new String[0]),-1,index->{sounds.add(remaining.get(index));error="";render();});}
    private void options(int index){List<String> options=new ArrayList<>();if(index>0)options.add("Move up");if(index+1<sounds.size())options.add("Move down");options.add("Remove sound");picker=SleepPicker.actions(activity,"Sound "+(index+1),options.toArray(new String[0]),options.stream().map(label->label.equals("Move up")?"up":label.equals("Move down")?"down":"trash").toArray(String[]::new),selected->{if(index>=sounds.size())return;String action=options.get(selected);if(action.equals("Remove sound"))sounds.remove(index);else Collections.swap(sounds,index,index+(action.equals("Move up")?-1:1));error="";render();});}
    void destroy(){if(picker!=null){picker.dismiss();picker=null;}}
    private void save(){if(previous==null)return;try{SoundMix next=previous.copy();next.rotation=new AmbientRotation(sounds,minutes);next.primary=AmbientRotation.NAME;next.validate();if(SoundPreferences.revision(preferences)!=revision)throw new IllegalStateException("The mix changed while this page was open. Cancel and reopen rotation before saving.");SleepSoundService.pauseForSelection();if(!SoundPreferences.saveIfRevision(preferences,revision,next))throw new IllegalStateException("The mix changed. Reopen this page before saving.");SoundPreferences.error(activity,"");SleepSoundService.update(activity);finished.run();}catch(RuntimeException invalid){error=invalid.getMessage()==null?"Rotation could not be saved.":invalid.getMessage();render();}}
}
